    const lc = document.createElement('canvas'); lc.width = W; lc.height = H; lc.getContext('2d').putImageData(lit, 0, 0);
    const pad = .14, gw = Math.max(8, Math.round(W * (1 + 2*pad) / 7)), gh = Math.max(8, Math.round(H * (1 + 2*pad) / 7));
    const mid = document.createElement('canvas'); mid.width = gw * 2; mid.height = gh * 2;
    mid.getContext('2d').drawImage(lc, pad / (1 + 2*pad) * gw * 2, pad / (1 + 2*pad) * gh * 2, gw * 2 / (1 + 2*pad), gh * 2 / (1 + 2*pad));
    const glow = document.createElement('canvas'); glow.width = gw; glow.height = gh;
