      if (artReady(d.kind)){
        const {w, h} = artSize(d);
        const pic = f >= 1 ? ART[d.kind] : isWire(d.kind) ? wireNight(d.kind, f) : nightArt(d.kind, f);
        g.drawImage(pic, d.x*k - w*k/2, d.y*k - h*k/2, w*k, h*k);
      }
