              ctx.fillStyle = '#fff'; ctx.strokeStyle = '#F2B544'; ctx.lineWidth = 2.5;
              ctx.beginPath(); ctx.rect(x*k - hs/2, y*k - hs/2, hs, hs); ctx.fill(); ctx.stroke();
