    const stale = () => {
      if ($('#aiResult').hidden || aiBusy) return;
      $('#aiResult').classList.add('rgai-stale'); $('#aiDownload').hidden = true;
      $('#aiCap').textContent = 'Settings changed. This image is from the previous settings; click Render again to update it.';
    };
    ['#aiScene', '#aiQuality'].forEach(id => $(id).addEventListener('change', stale));
    $('#aiExtra').addEventListener('input', stale);
